problem.answer_key:
DO $$
DECLARE
  rec RECORD;
  cur_status INT;
  cur_editor INT;
BEGIN
  FOR rec IN SELECT * FROM approval_actions ORDER BY action_id LOOP
    SELECT status, editor_id INTO cur_status, cur_editor FROM articles WHERE article_id = rec.article_id;
    IF rec.action_type = 1 AND cur_status = 0 THEN
      UPDATE articles SET status = 1, editor_id = rec.editor_id WHERE article_id = rec.article_id;
    ELSIF rec.action_type = 2 AND cur_status = 1 AND (cur_editor IS NULL OR cur_editor <> rec.editor_id) THEN
      UPDATE articles SET status = 2, editor_id = rec.editor_id WHERE article_id = rec.article_id;
    ELSIF rec.action_type = 3 AND cur_status = 1 THEN
      UPDATE articles SET status = 3, editor_id = rec.editor_id WHERE article_id = rec.article_id;
    ELSIF rec.action_type = 4 AND (cur_status = 1 OR cur_status = 3) THEN
      UPDATE articles SET status = 0, editor_id = NULL WHERE article_id = rec.article_id;
    END IF;
  END LOOP;
END $$;
SELECT * FROM articles ORDER BY article_id;

user_solution:
DO $$
DECLARE
    r RECORD;
    current_status INT;
    current_editor INT;
BEGIN
    FOR r IN SELECT * FROM approval_actions ORDER BY action_id LOOP
        SELECT status, editor_id INTO current_status, current_editor
        FROM articles
        WHERE article_id = r.article_id;

        --- 1= submit_for_review THEN 0=draft to 1=pending_review,
        IF r.action_type = 1 AND current_status = 0 THEN
            UPDATE articles 
            SET status = 1,
                editor_id = r.editor_id
            WHERE article_id = r.article_id;

        -- 2= approve 
        ELSIF r.action_type = 2 AND current_editor <> r.editor_id AND current_status = 1 THEN
            UPDATE articles
            SET status = 2,
                editor_id = r.editor_id
            WHERE article_id = r.article_id;

        -- 3=reject
        ELSIF r.action_type = 3 AND current_status = 1 THEN
            UPDATE articles
            SET status = 3,
                editor_id = r.editor_id
            WHERE article_id = r.article_id;

        --  4=withdraw)
        ELSIF r.action_type = 4 AND current_status IN (1, 3) THEN 
            UPDATE articles 
            SET status = 0,
                editor_id = NULL
            WHERE article_id = r.article_id;

        END IF;
    END LOOP;
END $$;

SELECT * FROM articles ORDER BY articles;
